var n = (flow.get('candump_restarts') || 0) + 1;
flow.set('candump_restarts', n);

var rc = (typeof msg.payload === 'object') ? JSON.stringify(msg.payload) : msg.payload;
node.warn('e-drive candump exited (rc ' + rc + ') — restart #' + n + ' in 5s');
node.status({ fill: 'red', shape: 'ring', text: 'candump exited (rc ' + rc + ') — restart #' + n });
return msg;

// candump -L lines, e.g.
//   (ts) can0 28A#F0852742C9365842        11-bit CANopen TPDO
//   (ts) can0 09F2058D#00FCFFFFFFFF00FF   N2K 127493 transmission
//   (ts) can0 14F00B65#009900004C040000   HCU 61451
// Also accepts a periodic {topic:'tick'} inject so staleness is still detected
// when the CAN bus goes completely silent (drives powered off at the dock).
// Decode map verified against the MFD 2026-08-17 - see GreenlineFindings.md.

const STALE_MS = 6000;          // no frames for this long -> Connected = 0
const PUBLISH_MS = 1000;        // dbus update rate per drive
const PUBLISH_COOLANT = false;  // 61453 identity UNVERIFIED - leave off (see findings)

const state = context.get('state') || { A: {}, B: {} };
const now = Date.now();

if (msg.topic !== 'tick') {
    let buf = context.get('buf') || '';
    buf += msg.payload.toString();
    const lines = buf.split('\n');
    buf = lines.pop();
    context.set('buf', buf);

    for (const line of lines) {
        const m = line.match(/can0\s+([0-9A-F]{3,8})#([0-9A-F]+)/);
        if (!m) continue;
        const id = m[1], data = m[2];

        if (id.length === 8) {
            const raw = parseInt(id, 16);
            const pgn = (raw >> 8) & 0x3FFFF;
            const sa = raw & 0xFF;
            const e = Buffer.from(data, 'hex');

            if (pgn === 0x1F205 && e.length >= 2) {
                // 127493: byte0 instance (00=port, 01=stbd), byte1 bits0-1 = gear.
                // Matched by PGN, not source address, since N2K addresses can renumber.
                const mt = e[0] === 0 ? 'A' : (e[0] === 1 ? 'B' : null);
                if (mt) {
                    const gear = e[1] & 0x03;   // 0=Fwd 1=Neutral(0xFD, confirmed) 2=Rev 3=Unknown
                    // Venus Motor/Direction enum: 0=Neutral 1=Reverse 2=Forward
                    if (gear !== 3) state[mt].direction = gear === 0 ? 2 : (gear === 2 ? 1 : 0);
                    state[mt].t = now;
                }
            } else if (pgn === 0xFF53 && e.length >= 3) {
                // 65363: byte0 instance, bytes1-2 LE = THROTTLE POSITION.
                // throttle% = raw / 9.280 exactly (4 settled plateaus, zero intercept).
                const mt = e[0] === 0 ? 'A' : (e[0] === 1 ? 'B' : null);
                if (mt) {
                    state[mt].throttle = e.readUInt16LE(1) / 9.280;
                    state[mt].t = now;
                }
            } else if (pgn === 0xF00B || pgn === 0xF00C || pgn === 0xF00D) {
                // HCU frames carry no instance byte -> discriminate on source address.
                // 0x64 = STARBOARD, 0x65 = PORT (proven by single-motor runs 2026-08-17).
                const mt = sa === 0x65 ? 'A' : (sa === 0x64 ? 'B' : null);
                if (!mt) continue;
                const s2 = state[mt];
                if (pgn === 0xF00B && e.length >= 2) {
                    s2.torquePct = e[1] - 125;          // J1939 percent torque, offset -125
                } else if (pgn === 0xF00C && e.length >= 6) {
                    // w2 -> motor DC current, fit r=0.9994 vs the MFD's MOTOR CURRENT.
                    // Sign flipped here so positive = motoring (drawing from the pack).
                    s2.dcCurrent = 800.409 - 0.024918 * e.readUInt16LE(2);
                    s2.phaseIpk = e.readUInt16LE(4) / 20;   // phase current, peak A
                } else if (pgn === 0xF00D && e.length >= 2) {
                    s2.coolant = e.readUInt16LE(0) / 256;   // UNVERIFIED scale
                }
                s2.t = now;
            }
            continue;
        }

        // 11-bit CANopen TPDOs: A = port (node 0x0A), B = starboard (0x0B)
        const mt = id.endsWith('A') ? 'A' : (id.endsWith('B') ? 'B' : null);
        if (!mt) continue;
        const s = state[mt];
        s.t = now;
        if (id[0] === '1') { s.status = parseInt(data.slice(0, 2), 16); continue; }
        if (data.length < 16) continue;
        const b = Buffer.from(data, 'hex');
        const f1 = b.readFloatLE(0), f2 = b.readFloatLE(4);
        switch (id[0]) {
            case '2': s.ctrlTemp = f1; s.motorTemp = f2; break;
            case '3': s.voltage = f1; s.phaseIrms = f2; break;
            // f1 is TORQUE in N.m -- NOT power x100W. Corrected 2026-08-17: T*w matched
            // the MFD (2.017 vs 2.0 kW, 2.56 vs 2.6) where x100W was 2.2x high.
            case '4': s.torque = f1; s.rpm = f2; break;
        }
    }
}
context.set('state', state);

const last = context.get('last') || { A: 0, B: 0 };
const conn = context.get('conn') || { A: null, B: null };
const out = [null, null, null];
const extra = {};

[['A', 0], ['B', 1]].forEach(([k, i]) => {
    const s = state[k];
    if (!s.t) return;                       // this drive has never been seen
    const fresh = (now - s.t) < STALE_MS;

    if (!fresh) {                           // CAN silent -> flag the device offline once
        if (conn[k] !== 0) { conn[k] = 0; out[i] = { payload: { Connected: 0 } }; }
        return;
    }
    if (now - last[k] < PUBLISH_MS) return;
    last[k] = now;

    const p = {};
    if (conn[k] !== 1) { conn[k] = 1; p.Connected = 1; }
    // clamp the tiny signed float noise around standstill so VRM never shows -1 rpm
    if (s.rpm != null) p['Motor/RPM'] = Math.abs(s.rpm) < 1 ? 0 : Math.round(s.rpm);
    if (s.voltage != null) p['Dc/0/Voltage'] = +s.voltage.toFixed(2);

    // Prefer the measured DC current from 61452. Fall back to mechanical power / V
    // (ignores drive losses, so a few % optimistic) if the HCU frame is missing.
    let amps = s.dcCurrent;
    if (amps == null && s.torque != null && s.rpm != null && s.voltage > 1) {
        amps = (s.torque * s.rpm * Math.PI / 30) / s.voltage;
    }
    if (amps != null) {
        p['Dc/0/Current'] = +amps.toFixed(2);
        if (s.voltage > 1) p['Dc/0/Power'] = +(s.voltage * amps).toFixed(0);
    }

    if (s.motorTemp != null) p['Motor/Temperature'] = +s.motorTemp.toFixed(1);
    if (s.ctrlTemp != null) p['Controller/Temperature'] = +s.ctrlTemp.toFixed(1);
    if (PUBLISH_COOLANT && s.coolant != null) p['Coolant/Temperature'] = +s.coolant.toFixed(1);
    if (s.direction != null) p['Motor/Direction'] = s.direction;

    if (Object.keys(p).length) out[i] = { payload: p };

    // Telemetry with no Victron dbus path -- available here for Signal K / MQTT.
    extra[k === 'A' ? 'port' : 'starboard'] = {
        torqueNm: s.torque != null ? +s.torque.toFixed(2) : null,
        torquePct: s.torquePct != null ? s.torquePct : null,
        throttlePct: s.throttle != null ? +s.throttle.toFixed(2) : null,
        phaseIrmsA: s.phaseIrms != null ? +s.phaseIrms.toFixed(1) : null,
        phaseIpkA: s.phaseIpk != null ? +s.phaseIpk.toFixed(1) : null,
        mechPowerW: (s.torque != null && s.rpm != null)
            ? Math.round(s.torque * s.rpm * Math.PI / 30) : null,
        running: s.status === 1
    };
});
context.set('last', last);
context.set('conn', conn);
if (Object.keys(extra).length) out[2] = { topic: 'gl6gk/extra', payload: extra };
return out;
